def max_subarray_with_indices(a: list[int]) -> tuple[int, int, int]:
    best = cur = a[0]
    start = end = tentative = 0
    for i in range(1, len(a)):
        if cur + a[i] < a[i]:
            cur = a[i]
            tentative = i
        else:
            cur += a[i]
        if cur > best:
            best = cur
            start, end = tentative, i
    return best, start, end
